 const reopen=async()=>{await H.clearDialogs();await H.save();await H.command('closeProject');await p().getByRole('button',{name:/^Deschide un proiect/}).waitFor();await H.answer(H.dir);await p().getByRole('button',{name:/^Deschide un proiect/}).first().click();await p().waitForSelector('.binder');await H.command('viewEditor');await H.select('doc-a');};
 const openPs=async tab=>{await native('projectSettings');await visible(ps());if(tab)await ps().locator('#ps-tab-'+tab).click();await H.wait(()=>pane().getAttribute('aria-labelledby').then(v=>v==='ps-tab-'+(tab||'sectiuni')));};
