     files['snapshots/doc-b/c.json']=JSON.stringify({name:'Beta QA',date:'2020-03-03T12:00:00Z',html:'<p>Autre UNIQUE QA.</p>'});files['snapshots/orphan-qa/d.json']=JSON.stringify({name:'Orphan QA',date:'2020-04-04T12:00:00Z',html:'<p>Orphan QA.</p>'});
