 team:c=>({setup:async()=>{await H.settingsFixture({team:{name:['no-name','configure'].includes(c.operation)?'':'Autor QA',color:'#123456',machine:'pc-self-qa'}});await H.fixture((pj,files)=>{const now=Date.now(),row=(who,doc,age,sample)=>({who,doc,time:new Date(now-age).toISOString(),machine:'pc-peer-qa',color:'#445566',added:5,removed:2,title:doc,sample});files['team/log-pc-peer-qa.jsonl']=[row('Ana QA','doc-a',0,'Recent QA'),row('agent','doc-b',3*864e5,'Agent QA'),row('Ana QA','doc-b',10*864e5,'Older QA'),row('Old QA','doc-a',40*864e5,'Ancient QA')].map(r=>JSON.stringify(r)).join('\n')+'\n';files['team/presence-pc-peer-qa.json']=JSON.stringify({who:'Ana QA',machine:'pc-peer-qa',color:'#445566',doc:'doc-b',locks:[],time:new Date(now).toISOString()});});},act:async s=>{await native('team');await visible(p().locator('.team-dialog'));const b=p().locator('.team-dialog');if(['no-name','configure'].includes(c.operation)){await b.getByRole('button',{name:'Setări → Partajare',exact:true}).click();if(c.operation==='configure'){const m=p().locator('.settings-dialog');await m.getByLabel('Numele tău',{exact:true}).fill('Autor configurat QA');await color(m.getByLabel('Culoarea ta',{exact:true}),'#654321');s.machine=await m.getByLabel('ID-ul acestui calculator',{exact:true}).inputValue();await m.getByRole('button',{name:'Salvează',exact:true}).click();}}else{await H.wait(()=>b.locator('.team-log li').count().then(n=>n>=2));if(c.operation==='all'||c.operation.startsWith('who-')||c.operation.startsWith('period-'))await b.locator('select').nth(0).selectOption('all');if(c.operation.startsWith('who-'))await b.locator('select').nth(1).selectOption({'who-all':'','who-ana':'Ana QA','who-agent':'agent'}[c.operation]);if(c.operation.startsWith('period-'))await b.locator('select').nth(2).selectOption({'period-all':'','period-day':'day','period-week':'week','period-month':'month'}[c.operation]);if(c.operation==='live-open')await b.locator('.team-live').getByRole('button',{name:'Al doilea document',exact:true}).click();if(c.operation==='log-open')await b.locator('.team-log li').first().getByRole('button').click();if(c.operation==='close')await button(b,'Închide').click();}},verify:async s=>{const b=p().locator('.team-dialog');const counts={doc:2,all:4,'who-all':4,'who-ana':2,'who-agent':1,'period-all':4,'period-day':1,'period-week':2,'period-month':3};if(c.operation in counts)H.assert(await b.locator('.team-log li').count()===counts[c.operation],'Team filter returns exact fixture records');if(c.operation==='who-agent')H.assert((await b.locator('.team-log').innerText()).includes('Agent QA'),'Agent entry retains sample/provenance');if(c.operation==='live-open'){await backEditor('doc-b');await H.command('back');await backEditor();}if(c.operation==='log-open'){await backEditor();H.assert(await b.count()===0,'Log open returns to editor and closes modal');}if(c.operation==='no-name'){const m=p().locator('.settings-dialog');H.assert(await m.getByRole('tab',{name:'Partajare',exact:true}).getAttribute('aria-selected')==='true','No-name route opens program Sharing settings');H.assert(await m.getByLabel('Numele tău',{exact:true}).inputValue()==='','No fictitious name filled implicitly');}if(c.operation==='configure'){const settings=await p().evaluate(()=>window.api.getSettings());H.assert(settings.team.name==='Autor configurat QA'&&settings.team.color==='#654321'&&settings.team.machine===s.machine,'Name/color and stable machine identity saved via real settings IPC');await native('team');H.assert((await p().locator('.team-dialog').innerText()).includes('Autor configurat QA'),'Configured identity displayed in Team');}if(c.operation==='close'){H.assert(await b.count()===0,'Team closes');await backEditor();}}}),
