 const sortAction=async(l,key,desired)=>{await l.click();for(let i=0;i<3&&await l.locator('..').getAttribute('aria-sort')!==desired;i++)await l.click();H.assert(await l.locator('..').getAttribute('aria-sort')===desired,'Sort action reaches '+key+' '+desired);};
